  default_transparent_start_circle: { en: 'Unfolded start edge by default', fr: 'Bord de départ déplié par défaut', de: 'Aufgefaltete Startkante als Standard', it: 'Bordo iniziale disteso come predefinito', es: 'Borde inicial desplegado por defecto', pt: 'Borda inicial desdobrada por padrão', he: 'קצה התחלה לא מקופל כברירת מחדל', ru: "Развёрнутый начальный край по умолчанию", fi: "Avattu alkureuna oletuksena", sv: "Utvikt startkant som standard", ja: "デフォルトで始点の縁を開く", zh: "默认展开起点边缘" },
  move_selected_only: { en: 'In move mode, allow only to move the selected strand', fr: 'En mode déplacement, déplacer uniquement le brin sélectionné', de: 'Im Bewegungsmodus nur den ausgewählten Strang bewegen', it: 'In modalità movimento, muovi solo il filo selezionato', es: 'En modo mover, mover solo la hebra seleccionada', pt: 'No modo mover, mover apenas a mecha selecionada', he: 'במצב הזזה, הזז רק את החוט הנבחר', ru: "В режиме перемещения разрешать двигать только выбранную прядь", fi: "Salli siirtotilassa vain valitun säikeen siirtäminen", sv: "Tillåt i flyttläge endast att flytta den valda strängen", ja: "移動モードでは選択中のストランドのみ移動を許可する", zh: "在移动模式下只允许移动选中的绳股" },
  show_cp_selected_only: { en: 'Show control points only for the selected strand', fr: 'Afficher les points de contrôle uniquement pour le brin sélectionné', de: 'Kontrollpunkte nur für den ausgewählten Strang anzeigen', it: 'Mostra i punti di controllo solo per il filo selezionato', es: 'Mostrar puntos de control solo para la hebra seleccionada', pt: 'Mostrar pontos de controle apenas para a mecha selecionada', he: 'הצג נקודות בקרה רק עבור החוט הנבחר', ru: "Показывать контрольные точки только выбранной пряди", fi: "Näytä ohjauspisteet vain valitulle säikeelle", sv: "Visa kontrollpunkter endast för den valda strängen", ja: "選択中のストランドの制御点のみ表示する", zh: "只显示选中绳股的控制点" },
  shadow_selected_only: { en: 'Cast shadow only for the selected strand', fr: `Projeter l'ombre uniquement pour le brin sélectionné`, de: 'Schatten nur für den ausgewählten Strang werfen', it: `Proietta l'ombra solo per il filo selezionato`, es: 'Proyectar sombra solo para la hebra seleccionada', pt: 'Projetar sombra apenas para a mecha selecionada', he: 'הטל צל רק עבור החוט הנבחר', ru: "Отбрасывать тень только от выбранной пряди", fi: "Heitä varjo vain valitulle säikeelle", sv: "Kasta skugga endast för den valda strängen", ja: "選択中のストランドのみ影を落とす", zh: "只为选中的绳股投射阴影" },
