  confirm_clear_history_title: { en: "Confirm Clear History", fr: "Confirmer la Suppression", de: "Löschen bestätigen", it: "Conferma Cancellazione Cronologia", es: "Confirmar Borrado de Historial", pt: "Confirmar Limpeza do Histórico", he: "אשר ניקוי היסטוריה", ru: "Подтвердите очистку истории", fi: "Vahvista historian tyhjennys", sv: "Bekräfta rensning av historik", ja: "履歴の消去を確認", zh: "确认清除历史" },
  confirm_clear_history_text: { en: "Are you sure you want to delete ALL past history sessions? This cannot be undone.", fr: "Êtes-vous sûr de vouloir supprimer TOUTES les sessions d'historique passées ? Cette action est irréversible.", de: "Möchten Sie WIRKLICH ALLE bisherigen Verlaufssitzungen löschen? Dies kann nicht rückgängig gemacht werden.", it: "Sei sicuro di voler eliminare TUTTE le sessioni di cronologia passate? Questa operazione non può essere annullata.", es: "¿Estás seguro de que deseas eliminar TODAS las sesiones de historial pasadas? Esto no se puede deshacer.", pt: "Tem certeza de que deseja excluir TODAS as sessões de histórico passadas? Isso não pode ser desfeito.", he: "האם אתה בטוח שברצונך למחוק את כל הפעלות ההיסטוריה הקודמות? לא ניתן לבטל פעולה זו.", ru: "Вы уверены, что хотите удалить ВСЕ прошлые сеансы истории? Это действие нельзя отменить.", fi: "Haluatko varmasti poistaa KAIKKI aiemmat historiaistunnot? Tätä ei voi kumota.", sv: "Är du säker på att du vill ta bort ALLA tidigare historiksessioner? Detta kan inte ångras.", ja: "過去の履歴セッションをすべて削除してもよろしいですか? この操作は元に戻せません。", zh: "确定要删除所有过去的历史会话吗? 此操作无法撤销。" },
  history_cleared_text: { en: "All past history sessions have been cleared.", fr: "Toutes les sessions d'historique passées ont été effacées.", de: "Alle bisherigen Verlaufssitzungen wurden gelöscht.", it: "Tutte le sessioni di cronologia passate sono state cancellate.", es: "Todas las sesiones de historial pasadas han sido borradas.", pt: "Todas as sessões de histórico passadas foram limpas.", he: "כל הפעלות ההיסטוריה הקודמות נוקו.", ru: "Все прошлые сеансы истории удалены.", fi: "Kaikki aiemmat historiaistunnot on tyhjennetty.", sv: "Alla tidigare historiksessioner har rensats.", ja: "過去の履歴セッションをすべて消去しました。", zh: "所有过去的历史会话已清除。" },
  toggle_shadow_tooltip: { en: "Enable/disable shadow effects for overlapping strands", fr: "Activer/désactiver les ombres\ndes brins qui se chevauchent", de: "Schatteneffekte für überlappende\nStränge ein-/ausschalten", it: "Attiva/disattiva le ombre\ndei fili sovrapposti", es: "Activar/desactivar sombras\nde los cordones superpuestos", pt: "Ativar/desativar sombras\ndas mechas sobrepostas", he: "הפעלה/כיבוי של אפקטי צל\nלחוטים חופפים", ru: "Включить/выключить тени\nдля пересекающихся прядей", fi: "Ota varjot käyttöön tai pois\npäällekkäisille säikeille", sv: "Slå på/av skuggeffekter\nför överlappande strängar", ja: "重なるストランドの\n影効果を有効/無効にする", zh: "启用/禁用重叠绳股的阴影效果" },
