  finnish: { en: "Finnish", fr: "Finnois", de: "Finnisch", it: "Finlandese", es: "Finés", pt: "Finlandês", he: "פינית", ru: "Финский", fi: "Suomi", sv: "Finska", ja: "フィンランド語", zh: "芬兰语" },
