  end_style_preview: { en: "Preview", fr: "Aperçu", de: "Vorschau", it: "Anteprima", es: "Vista previa", pt: "Pré-visualização", he: "תצוגה מקדימה", ru: "Предпросмотр", fi: "Esikatselu", sv: "Förhandsvisning", ja: "プレビュー", zh: "预览" },
  end_style_live_hint: { en: "Changes show on the canvas immediately. Cancel puts the end back exactly as it was.", fr: "Les changements apparaissent immédiatement sur le canevas. Annuler remet l'extrémité exactement comme elle était.", de: "Änderungen erscheinen sofort auf der Leinwand. Abbrechen setzt das Ende genau so zurück, wie es war.", it: "Le modifiche compaiono subito sulla tela. Annulla riporta l'estremità esattamente com'era.", es: "Los cambios se muestran de inmediato en el lienzo. Cancelar deja el extremo exactamente como estaba.", pt: "As alterações aparecem imediatamente na tela. Cancelar repõe a extremidade exatamente como estava.", he: "השינויים מופיעים מיד על הקנבס. ביטול מחזיר את הקצה בדיוק כפי שהיה.", ru: "Изменения сразу видны на холсте. «Отмена» возвращает конец в точности к прежнему виду.", fi: "Muutokset näkyvät piirtoalueella heti. Peruuta palauttaa pään täsmälleen ennalleen.", sv: "Ändringar visas på arbetsytan direkt. Avbryt sätter tillbaka änden exakt som den var.", ja: "変更はすぐにキャンバスに反映されます。キャンセルすると端は元の状態に戻ります。", zh: "更改会立即显示在画布上。取消会将末端恢复到原来的状态。" },
  end_shape: { en: "End Shape", fr: "Forme de l'extrémité", de: "Endform", it: "Forma dell'estremità", es: "Forma del extremo", pt: "Forma da extremidade", he: "צורת הקצה", ru: "Форма конца", fi: "Pään muoto", sv: "Ändform", ja: "端の形", zh: "末端形状" },
