  end_shape_notched: { en: "Notched", fr: "Entaillée", de: "Eingekerbt", it: "Intagliata", es: "Con muesca", pt: "Entalhada", he: "חרוץ", ru: "С вырезом", fi: "Lovettu", sv: "Skårad", ja: "切り欠き", zh: "缺口" },
  end_shape_concave: { en: "Concave", fr: "Concave", de: "Konkav", it: "Concava", es: "Cóncavo", pt: "Côncava", he: "קעור", ru: "Вогнутый", fi: "Kovera", sv: "Konkav", ja: "凹み", zh: "凹陷" },
  end_tilt: { en: "Tilt", fr: "Inclinaison", de: "Neigung", it: "Inclinazione", es: "Inclinación", pt: "Inclinação", he: "הטיה", ru: "Наклон", fi: "Kallistus", sv: "Lutning", ja: "傾き", zh: "倾斜" },
  end_tilt_hint: { en: "Rotate the end edge around the endpoint. 0° is square to the strand.", fr: "Fait pivoter le bord de l'extrémité autour du point final. 0° est perpendiculaire au brin.", de: "Dreht die Endkante um den Endpunkt. 0° steht senkrecht zum Strang.", it: "Ruota il bordo dell'estremità attorno al punto finale. 0° è perpendicolare al filo.", es: "Gira el borde del extremo alrededor del punto final. 0° es perpendicular a la hebra.", pt: "Roda a aresta da extremidade em torno do ponto final. 0° é perpendicular ao fio.", he: "מסובב את שפת הקצה סביב נקודת הקצה. 0° ניצב לחוט.", ru: "Поворачивает край конца вокруг конечной точки. 0° — перпендикулярно пряди.", fi: "Kiertää pään reunaa päätepisteen ympäri. 0° on kohtisuorassa säikeeseen.", sv: "Roterar ändkanten runt ändpunkten. 0° är vinkelrätt mot strängen.", ja: "端点を中心に端の辺を回転させます。0° はストランドに直角です。", zh: "围绕端点旋转末端边缘。0° 表示与绳股垂直。" },
  end_depth: { en: "Depth", fr: "Profondeur", de: "Tiefe", it: "Profondità", es: "Profundidad", pt: "Profundidade", he: "עומק", ru: "Глубина", fi: "Syvyys", sv: "Djup", ja: "深さ", zh: "深度" },
  end_depth_hint: { en: "How far the shape reaches, as a share of the strand's width.", fr: "Portée de la forme, en proportion de la largeur du brin.", de: "Wie weit die Form reicht, als Anteil der Strangbreite.", it: "Quanto si estende la forma, in proporzione alla larghezza del filo.", es: "Hasta dónde llega la forma, como proporción del ancho de la hebra.", pt: "Até onde a forma chega, como fração da largura do fio.", he: "עד כמה הצורה מגיעה, כחלק מרוחב החוט.", ru: "Насколько далеко заходит форма, в долях ширины пряди.", fi: "Kuinka pitkälle muoto ulottuu, osuutena säikeen leveydestä.", sv: "Hur långt formen når, som en andel av strängens bredd.", ja: "形がどこまで届くかを、ストランド幅に対する割合で指定します。", zh: "形状延伸的距离，以绳股宽度的比例表示。" },
  end_extend_trim: { en: "Extend / Trim", fr: "Prolonger / Raccourcir", de: "Verlängern / Kürzen", it: "Estendi / Accorcia", es: "Extender / Recortar", pt: "Estender / Aparar", he: "הארכה / קיצור", ru: "Удлинить / укоротить", fi: "Pidennä / lyhennä", sv: "Förläng / korta", ja: "延長 / 切り詰め", zh: "延长 / 修剪" },
  end_extend_trim_hint: { en: "+ extends past the endpoint, − trims. The endpoint itself never moves.", fr: "+ prolonge au-delà du point final, − raccourcit. Le point final lui-même ne bouge jamais.", de: "+ verlängert über den Endpunkt hinaus, − kürzt. Der Endpunkt selbst bewegt sich nie.", it: "+ estende oltre il punto finale, − accorcia. Il punto finale non si sposta mai.", es: "+ extiende más allá del punto final, − recorta. El punto final nunca se mueve.", pt: "+ estende para além do ponto final, − apara. O ponto final nunca se move.", he: "+ מאריך מעבר לנקודת הקצה, − מקצר. נקודת הקצה עצמה לעולם לא זזה.", ru: "+ удлиняет за конечную точку, − укорачивает. Сама конечная точка не сдвигается.", fi: "+ pidentää päätepisteen yli, − lyhentää. Päätepiste itse ei koskaan liiku.", sv: "+ förlänger förbi ändpunkten, − kortar. Själva ändpunkten flyttas aldrig.", ja: "+ は端点の先へ延長、− は切り詰めます。端点そのものは動きません。", zh: "+ 向端点外延长，− 修剪。端点本身不会移动。" },
  side_line_section: { en: "Side Line", fr: "Ligne latérale", de: "Seitenlinie", it: "Linea laterale", es: "Línea lateral", pt: "Linha lateral", he: "קו צד", ru: "Боковая линия", fi: "Sivuviiva", sv: "Sidolinje", ja: "サイドライン", zh: "侧线" },
  show_side_line: { en: "Show side line", fr: "Afficher la ligne latérale", de: "Seitenlinie anzeigen", it: "Mostra linea laterale", es: "Mostrar línea lateral", pt: "Mostrar linha lateral", he: "הצג קו צד", ru: "Показывать боковую линию", fi: "Näytä sivuviiva", sv: "Visa sidolinje", ja: "サイドラインを表示", zh: "显示侧线" },
  side_line_thickness: { en: "Thickness", fr: "Épaisseur", de: "Stärke", it: "Spessore", es: "Grosor", pt: "Espessura", he: "עובי", ru: "Толщина", fi: "Paksuus", sv: "Tjocklek", ja: "太さ", zh: "粗细" },
